+                keywords.some(kw => key.toLowerCase().includes(kw.toLowerCase()))
+              );
+              return matchedKey ? row[matchedKey] : '';
+            };
+
+            const code = findValue(['code', 'product_code', 'รหัส', 'รหัสสินค้า']);
